use std::borrow::Cow;
use std::io::{self, Write};
use std::process::ExitCode;
use std::sync::mpsc;

use wgpu::util::DeviceExt;

const WORKGROUP_SIZE: u32 = 256;
const HIST_BINS_MAX: u32 = 256;

/// Two kernels share one bind group:
/// - `generate_values` computes each value on the GPU and stores it.
/// - `count_bins` maps each value to its bin and adds one to it atomically.
const SHADER: &str = r#"
struct Params {
    count: u32,
    seed: u32,
    bins: u32,
    pad: u32,
}

@group(0) @binding(0) var<uniform> params: Params;
@group(0) @binding(1) var<storage, read_write> values: array<u32>;
@group(0) @binding(2) var<storage, read_write> hist: array<atomic<u32>, 256>;

fn value_of(i: i32, seed: i32) -> i32 {
    let a = ((i % 40000) * 1597 + seed + 51749) % 40000;
    let b = (a * a + a * 37 + 11) % 40009;
    let c = (b * 613 + 7919) % 40009;
    let d = (c + (i / 40000) * 7919) % 40009;
    return d % 1000;
}

@compute @workgroup_size(256)
fn generate_values(@builtin(global_invocation_id) gid: vec3<u32>) {
    let i = gid.x;
    if (i >= params.count) {
        return;
    }
    values[i] = u32(value_of(i32(i), i32(params.seed)));
}

@compute @workgroup_size(256)
fn count_bins(@builtin(global_invocation_id) gid: vec3<u32>) {
    let i = gid.x;
    if (i >= params.count) {
        return;
    }
    let bin = values[i] * params.bins / 1000u;
    atomicAdd(&hist[bin], 1u);
}
"#;

struct Job {
    count: u32,
    seed: u32,
    bins: u32,
}

fn read_job(path: &str) -> Result<Job, String> {
    let text = std::fs::read_to_string(path).map_err(|e| format!("cannot read {path}: {e}"))?;
    let fields: Vec<&str> = text.split_whitespace().collect();
    if fields.len() != 3 {
        return Err(format!("expected 3 numbers in {path}, found {}", fields.len()));
    }
    let parse = |s: &str| {
        s.parse::<u32>()
            .map_err(|e| format!("bad number {s:?} in {path}: {e}"))
    };
    let job = Job {
        count: parse(fields[0])?,
        seed: parse(fields[1])?,
        bins: parse(fields[2])?,
    };
    if job.count > 4_000_000 || job.seed > 9999 || job.bins == 0 || job.bins > HIST_BINS_MAX {
        return Err(format!("parameters out of range in {path}"));
    }
    Ok(job)
}

fn run_gpu(job: &Job) -> Result<Vec<u32>, String> {
    let instance = wgpu::Instance::new(wgpu::InstanceDescriptor::new_without_display_handle());
    let adapter = pollster::block_on(instance.request_adapter(&wgpu::RequestAdapterOptions {
        power_preference: wgpu::PowerPreference::HighPerformance,
        ..Default::default()
    }))
    .map_err(|e| format!("no GPU adapter: {e}"))?;
    let (device, queue) = pollster::block_on(adapter.request_device(&wgpu::DeviceDescriptor::default()))
        .map_err(|e| format!("no GPU device: {e}"))?;

    let shader = device.create_shader_module(wgpu::ShaderModuleDescriptor {
        label: Some("histogram"),
        source: wgpu::ShaderSource::Wgsl(Cow::Borrowed(SHADER)),
    });

    let params = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: Some("params"),
        contents: bytemuck::cast_slice(&[job.count, job.seed, job.bins, 0u32]),
        usage: wgpu::BufferUsages::UNIFORM,
    });

    // Never zero-sized: wgpu rejects empty storage bindings, and count may be 0.
    let values_bytes = u64::from(job.count.max(1)) * 4;
    let values = device.create_buffer(&wgpu::BufferDescriptor {
        label: Some("values"),
        size: values_bytes,
        usage: wgpu::BufferUsages::STORAGE,
        mapped_at_creation: false,
    });

    let hist_bytes = u64::from(HIST_BINS_MAX) * 4;
    let hist = device.create_buffer(&wgpu::BufferDescriptor {
        label: Some("hist"),
        size: hist_bytes,
        usage: wgpu::BufferUsages::STORAGE | wgpu::BufferUsages::COPY_SRC,
        mapped_at_creation: false,
    });

    let readback = device.create_buffer(&wgpu::BufferDescriptor {
        label: Some("readback"),
        size: hist_bytes,
        usage: wgpu::BufferUsages::MAP_READ | wgpu::BufferUsages::COPY_DST,
        mapped_at_creation: false,
    });

    let storage = |binding: u32, ty: wgpu::BufferBindingType| wgpu::BindGroupLayoutEntry {
        binding,
        visibility: wgpu::ShaderStages::COMPUTE,
        ty: wgpu::BindingType::Buffer {
            ty,
            has_dynamic_offset: false,
            min_binding_size: None,
        },
        count: None,
    };
    let bind_group_layout = device.create_bind_group_layout(&wgpu::BindGroupLayoutDescriptor {
        label: Some("histogram layout"),
        entries: &[
            storage(0, wgpu::BufferBindingType::Uniform),
            storage(1, wgpu::BufferBindingType::Storage { read_only: false }),
            storage(2, wgpu::BufferBindingType::Storage { read_only: false }),
        ],
    });
    let pipeline_layout = device.create_pipeline_layout(&wgpu::PipelineLayoutDescriptor {
        label: Some("histogram pipeline layout"),
        bind_group_layouts: &[Some(&bind_group_layout)],
        immediate_size: 0,
    });
    let bind_group = device.create_bind_group(&wgpu::BindGroupDescriptor {
        label: Some("histogram bind group"),
        layout: &bind_group_layout,
        entries: &[
            wgpu::BindGroupEntry {
                binding: 0,
                resource: params.as_entire_binding(),
            },
            wgpu::BindGroupEntry {
                binding: 1,
                resource: values.as_entire_binding(),
            },
            wgpu::BindGroupEntry {
                binding: 2,
                resource: hist.as_entire_binding(),
            },
        ],
    });

    let make_pipeline = |entry_point: &str| {
        device.create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
            label: Some(entry_point),
            layout: Some(&pipeline_layout),
            module: &shader,
            entry_point: Some(entry_point),
            compilation_options: Default::default(),
            cache: None,
        })
    };
    let generate = make_pipeline("generate_values");
    let count = make_pipeline("count_bins");

    let groups = job.count.div_ceil(WORKGROUP_SIZE);
    let mut encoder = device.create_command_encoder(&wgpu::CommandEncoderDescriptor {
        label: Some("histogram"),
    });
    {
        let mut pass = encoder.begin_compute_pass(&wgpu::ComputePassDescriptor::default());
        pass.set_pipeline(&generate);
        pass.set_bind_group(0, &bind_group, &[]);
        pass.dispatch_workgroups(groups, 1, 1);
    }
    {
        let mut pass = encoder.begin_compute_pass(&wgpu::ComputePassDescriptor::default());
        pass.set_pipeline(&count);
        pass.set_bind_group(0, &bind_group, &[]);
        pass.dispatch_workgroups(groups, 1, 1);
    }
    encoder.copy_buffer_to_buffer(&hist, 0, &readback, 0, hist_bytes);
    queue.submit(Some(encoder.finish()));

    let slice = readback.slice(..);
    let (tx, rx) = mpsc::channel();
    slice.map_async(wgpu::MapMode::Read, move |result| {
        let _ = tx.send(result);
    });
    device
        .poll(wgpu::PollType::wait_indefinitely())
        .map_err(|e| format!("GPU poll failed: {e}"))?;
    rx.recv()
        .map_err(|e| format!("map callback lost: {e}"))?
        .map_err(|e| format!("readback failed: {e}"))?;

    let counts: Vec<u32> = {
        let view = slice.get_mapped_range();
        bytemuck::cast_slice::<u8, u32>(&view)[..job.bins as usize].to_vec()
    };
    readback.unmap();
    Ok(counts)
}

fn main() -> ExitCode {
    let Some(path) = std::env::args().nth(1) else {
        eprintln!("usage: gpu_histogram <job-file>");
        return ExitCode::FAILURE;
    };

    let job = match read_job(&path) {
        Ok(job) => job,
        Err(e) => {
            eprintln!("error: {e}");
            return ExitCode::FAILURE;
        }
    };
    let counts = match run_gpu(&job) {
        Ok(counts) => counts,
        Err(e) => {
            eprintln!("error: {e}");
            return ExitCode::FAILURE;
        }
    };

    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    let write_all = |out: &mut io::BufWriter<io::StdoutLock>| -> io::Result<()> {
        for (index, n) in counts.iter().enumerate() {
            writeln!(out, "BIN {index} {n}")?;
        }
        writeln!(out, "TOTAL {}", job.count)?;
        out.flush()
    };
    if let Err(e) = write_all(&mut out) {
        eprintln!("error: cannot write output: {e}");
        return ExitCode::FAILURE;
    }
    ExitCode::SUCCESS
}

